static readonly SemaphoreSlim _gate = new(1, 1);   // 1 free slot out of 1

await _gate.WaitAsync();   // slot free → right away; none → wait, thread free
try
{
    await WriteToFileAsync(data);   // only we are inside
}
finally
{
    _gate.Release();       // the slot goes to the next waiter
}

