async Task SaveAsync()
{
    await _gate.WaitAsync();            // 1) slot taken, count 0
    try     { await FlushAsync(); }     // 2) waiting for FlushAsync…
    finally { _gate.Release(); }        // 3) …and we never reach Release
}
async Task FlushAsync()
{
    await _gate.WaitAsync();            // 2) no slot — waits forever
    try     { await WriteAsync(); }
    finally { _gate.Release(); }
}

